def get_transcripts(url, lang=None, enableParagraphs=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0009000" if __import__("os").path.isdir("./environment_mix/0009000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    # --- helpers ---
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        # deterministic-ish unique id: prefix_YYYYMMDDHHMMSS_random
        import secrets
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
        return f"{prefix}_{ts}_{secrets.token_hex(8)}"

    def _norm_lang(s):
        return s

    def _parse_video_id(inp):
        if not isinstance(inp, str):
            return None
        s = inp.strip()
        if not s:
            return None

        # Accept raw IDs (tolerant length 6-20) and URLs
        # Extract candidates from known patterns.
        candidates = []

        # If user passed something like "youtu.be/<id>" or full URL
        # We'll find v=<id> or /shorts/<id> or youtu.be/<id> or /embed/<id>
        m = re.search(r"(?:\?|&|#)v=([A-Za-z0-9_-]{6,20})", s)
        if m:
            candidates.append(m.group(1))
        m = re.search(r"youtu\.be/([A-Za-z0-9_-]{6,20})", s)
        if m:
            candidates.append(m.group(1))
        m = re.search(r"/shorts/([A-Za-z0-9_-]{6,20})", s)
        if m:
            candidates.append(m.group(1))
        m = re.search(r"/embed/([A-Za-z0-9_-]{6,20})", s)
        if m:
            candidates.append(m.group(1))

        # Raw id fallback: entire string must match allowed charset and length
        if re.fullmatch(r"[A-Za-z0-9_-]{6,20}", s):
            candidates.append(s)

        if not candidates:
            return None
        vid = candidates[0]
        if not (6 <= len(vid) <= 20):
            return None
        if not re.fullmatch(r"[A-Za-z0-9_-]+", vid):
            return None
        return vid

    def _format_plain(segments):
        # segments: list of dicts with text
        parts = []
        for seg in segments:
            t = seg.get("text", "")
            if isinstance(t, str) and t:
                parts.append(t.strip())
        # normalize internal whitespace a bit, but keep faithful
        text = " ".join([p for p in parts if p])
        text = re.sub(r"\s+", " ", text).strip()
        return text

    def _format_paragraphs(segments):
        # simple heuristic: start a new paragraph after >= 5 seconds gap
        paras = []
        cur = []
        prev_end = None
        for seg in segments:
            try:
                start = int(seg.get("start_ms", 0))
                end = int(seg.get("end_ms", start + int(seg.get("duration_ms", 0))))
            except Exception:
                start, end = 0, 0
            text = seg.get("text", "")
            if not isinstance(text, str):
                text = ""
            text = text.strip()
            if not text:
                prev_end = end
                continue

            if prev_end is not None and (start - prev_end) >= 5000 and cur:
                paras.append(" ".join(cur).strip())
                cur = []
            cur.append(text)
            prev_end = end
        if cur:
            paras.append(" ".join(cur).strip())
        # collapse whitespace within paragraphs
        paras = [re.sub(r"\s+", " ", p).strip() for p in paras if p.strip()]
        return "\n\n".join(paras).strip()

    # Service dynamics / logging + limits
    def _log_call(status_code, request_id=None, request_key=None, video_id=None, track_id=None, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("log"),
            "endpoint": "get_transcripts",
            "status": status_code,
            "request_id": request_id,
            "request_key": request_key,
            "video_id": video_id,
            "track_id": track_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now()
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        # If no config exists, do not enforce.
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            return None
        rate = cfg.get("rate_limit_per_minute")
        daily = cfg.get("daily_quota")
        now = datetime.datetime.utcnow()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if isinstance(rate, int) and rate >= 0:
            cutoff = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                ts = r.get("created_at")
                if isinstance(ts, str):
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= cutoff:
                        cnt += 1
            if cnt >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(daily, int) and daily >= 0:
            cutoff = now - datetime.timedelta(days=1)
            cnt = 0
            for r in logs:
                ts = r.get("created_at")
                if isinstance(ts, str):
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= cutoff:
                        cnt += 1
            if cnt >= daily:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    # --- validate inputs ---
    if not isinstance(url, str) or not url.strip():
        err = _err("VALIDATION_ERROR", "url must be a non-empty string.")
        try: _log_call("error", error_code=err["error"]["code"], error_message=err["error"]["message"])
        except Exception: pass
        return err

    if lang is None:
        lang = "en"
    if not isinstance(lang, str):
        err = _err("VALIDATION_ERROR", "lang must be a string.")
        try: _log_call("error", error_code=err["error"]["code"], error_message=err["error"]["message"])
        except Exception: pass
        return err
    if not (2 <= len(lang) <= 12):
        err = _err("VALIDATION_ERROR", "lang length must be between 2 and 12.")
        try: _log_call("error", error_code=err["error"]["code"], error_message=err["error"]["message"])
        except Exception: pass
        return err
    lang = _norm_lang(lang)

    if enableParagraphs is None:
        enableParagraphs = False
    if not isinstance(enableParagraphs, bool):
        err = _err("VALIDATION_ERROR", "enableParagraphs must be a boolean.")
        try: _log_call("error", error_code=err["error"]["code"], error_message=err["error"]["message"])
        except Exception: pass
        return err

    limerr = _enforce_limits()
    if limerr:
        try: _log_call("error", error_code=limerr["error"]["code"], error_message=limerr["error"]["message"])
        except Exception: pass
        return limerr

    # --- create transcript_request row (received) ---
    normalized_video_id = _parse_video_id(url)
    # request_key is computed AFTER normalization; if normalization fails we still create request with failed status.
    reqs = _load("transcript_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    now = _now()
    request_id = _gen_id("req")

    if normalized_video_id is None:
        req_row = {
            "id": request_id,
            "request_key": _gen_id("rk_invalid"),  # must be unique, but unusable without normalized id
            "input_url": url,
            "normalized_video_id": None,
            "video_id": None,
            "lang": lang,
            "enable_paragraphs": enableParagraphs,
            "response_text": None,
            "track_id": None,
            "status": "failed",
            "error_code": "INVALID_URL",
            "error_message": "Could not parse a valid YouTube video id from url.",
            "processing_ms": int((time.time() - _t0) * 1000),
            "created_at": now,
            "updated_at": now
        }
        reqs.append(req_row)
        _save("transcript_requests.json", reqs)
        try: _log_call("error", request_id=request_id, error_code="INVALID_URL", error_message=req_row["error_message"])
        except Exception: pass
        return _err("VALIDATION_ERROR", req_row["error_message"], error_code="INVALID_URL")

    rk_src = f"{normalized_video_id}|{lang}|{str(enableParagraphs).lower()}"
    request_key = hashlib.sha256(rk_src.encode("utf-8")).hexdigest()

    # Dedupe: if succeeded cached, return response_text
    existing = None
    for r in reqs:
        if r.get("request_key") == request_key:
            existing = r
            break
    if existing and existing.get("status") == "succeeded" and isinstance(existing.get("response_text"), str):
        try: _log_call("ok_cached", request_id=existing.get("id"), request_key=request_key, video_id=existing.get("video_id"), track_id=existing.get("track_id"))
        except Exception: pass
        return {
            "request": existing,
            "transcript": {
                "text": existing["response_text"],
                "lang": existing.get("lang"),
                "enableParagraphs": existing.get("enable_paragraphs")
            },
            "cached": True
        }

    # Create new request (received)
    req_row = {
        "id": request_id,
        "request_key": request_key,
        "input_url": url,
        "normalized_video_id": normalized_video_id,
        "video_id": None,
        "lang": lang,
        "enable_paragraphs": enableParagraphs,
        "response_text": None,
        "track_id": None,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "processing_ms": None,
        "created_at": now,
        "updated_at": now
    }
    reqs.append(req_row)
    _save("transcript_requests.json", reqs)

    # Transition received -> processing
    def _transition_request(new_status, error_code=None, error_message=None, processing_ms=None):
        # enforce lifecycle transitions
        allowed = {
            "received": ["processing", "failed"],
            "processing": ["succeeded", "failed"],
            "succeeded": [],
            "failed": []
        }
        cur = req_row.get("status")
        if new_status not in allowed.get(cur, []):
            return _err("INVALID_TRANSITION", f"Invalid request status transition {cur} -> {new_status}.")
        req_row["status"] = new_status
        req_row["updated_at"] = _now()
        if error_code is not None:
            req_row["error_code"] = error_code
        if error_message is not None:
            req_row["error_message"] = error_message
        if processing_ms is not None:
            req_row["processing_ms"] = processing_ms
        # persist update
        for i, r in enumerate(reqs):
            if r.get("id") == req_row["id"]:
                reqs[i] = req_row
                break
        _save("transcript_requests.json", reqs)
        return None

    terr = _transition_request("processing")
    if terr:
        try: _log_call("error", request_id=request_id, request_key=request_key, error_code=terr["error"]["code"], error_message=terr["error"]["message"])
        except Exception: pass
        return terr

    # --- resolve/create video row ---
    videos = _load("videos.json")
    if not isinstance(videos, list):
        videos = []
    video_row = None
    for v in videos:
        if v.get("youtube_video_id") == normalized_video_id:
            video_row = v
            break
    if video_row is None:
        vid_id = _gen_id("vid")
        canonical_url = f"https://www.youtube.com/watch?v={normalized_video_id}"
        now2 = _now()
        video_row = {
            "id": vid_id,
            "youtube_video_id": normalized_video_id,
            "canonical_url": canonical_url,
            "title": None,
            "channel_id": None,
            "duration_seconds": None,
            "status": "active",
            "created_at": now2,
            "updated_at": now2
        }
        videos.append(video_row)
        _save("videos.json", videos)

    req_row["video_id"] = video_row.get("id")
    req_row["updated_at"] = _now()
    for i, r in enumerate(reqs):
        if r.get("id") == req_row["id"]:
            reqs[i] = req_row
            break
    _save("transcript_requests.json", reqs)

    # --- resolve track ---
    tracks = _load("transcript_tracks.json")
    if not isinstance(tracks, list):
        tracks = []

    track_row = None
    for t in tracks:
        if t.get("video_id") == video_row["id"] and t.get("lang") == lang:
            track_row = t
            break

    if track_row and track_row.get("status") == "available":
        # produce response from stored segments
        segments = _load("transcript_segments.json")
        if not isinstance(segments, list):
            segments = []
        segs = [s for s in segments if s.get("track_id") == track_row.get("id")]
        # order by seq
        try:
            segs.sort(key=lambda x: int(x.get("seq", 0)))
        except Exception:
            pass

        # maintain invariant segment_count == count(segments)
        if isinstance(track_row.get("segment_count"), int) and track_row.get("segment_count") != len(segs):
            track_row["segment_count"] = len(segs)
            track_row["updated_at"] = _now()
            for i, t in enumerate(tracks):
                if t.get("id") == track_row["id"]:
                    tracks[i] = track_row
                    break
            _save("transcript_tracks.json", tracks)

        text = _format_paragraphs(segs) if enableParagraphs else _format_plain(segs)

        # request processing -> succeeded
        req_row["track_id"] = track_row.get("id")
        req_row["response_text"] = text
        perr = _transition_request("succeeded", processing_ms=int((time.time() - _t0) * 1000))
        if perr:
            try: _log_call("error", request_id=request_id, request_key=request_key, video_id=video_row.get("id"), track_id=track_row.get("id"), error_code=perr["error"]["code"], error_message=perr["error"]["message"])
            except Exception: pass
            return perr

        # persist request fields updated by side effects above
        for i, r in enumerate(reqs):
            if r.get("id") == req_row["id"]:
                reqs[i] = req_row
                break
        _save("transcript_requests.json", reqs)

        try: _log_call("ok", request_id=request_id, request_key=request_key, video_id=video_row.get("id"), track_id=track_row.get("id"))
        except Exception: pass
        return {
            "request": req_row,
            "video": video_row,
            "track": track_row,
            "transcript": {"text": text, "lang": lang, "enableParagraphs": enableParagraphs},
            "cached": False
        }

    # If track exists and is unavailable, fail request accordingly
    if track_row and track_row.get("status") == "unavailable":
        req_row["track_id"] = track_row.get("id")
        for i, r in enumerate(reqs):
            if r.get("id") == req_row["id"]:
                reqs[i] = req_row
                break
        _save("transcript_requests.json", reqs)
        _transition_request(
            "failed",
            error_code="TRANSCRIPT_UNAVAILABLE",
            error_message=track_row.get("failure_reason") or "Transcript unavailable for requested language.",
            processing_ms=int((time.time() - _t0) * 1000)
        )
        try: _log_call("error", request_id=request_id, request_key=request_key, video_id=video_row.get("id"), track_id=track_row.get("id"), error_code="TRANSCRIPT_UNAVAILABLE", error_message=req_row.get("error_message"))
        except Exception: pass
        return _err("NOT_FOUND", "Transcript unavailable for requested language.", error_code="TRANSCRIPT_UNAVAILABLE")

    # --- "fetch" transcript: offline behavior ---
    # No upstream available. Treat as unavailable and persist track/status + fail request.
    def _upsert_track_unavailable(reason):
        nonlocal track_row
        now3 = _now()
        if track_row is None:
            track_row = {
                "id": _gen_id("trk"),
                "video_id": video_row["id"],
                "lang": lang,
                "is_auto_generated": None,
                "source": "youtube_transcript_api",
                "raw_payload": None,
                "segment_count": 0,
                "text_plain": None,
                "status": "fetching",  # must go through fetching per lifecycle
                "last_fetched_at": None,
                "failure_reason": None,
                "created_at": now3,
                "updated_at": now3
            }
            tracks.append(track_row)
            _save("transcript_tracks.json", tracks)
        # transition to fetching if allowed/needed
        allowed = {
            "fetching": ["available", "failed", "unavailable"],
            "available": ["fetching", "unavailable"],
            "failed": ["fetching", "unavailable"],
            "unavailable": ["fetching"]
        }
        cur = track_row.get("status")
        if cur != "fetching":
            if "fetching" not in allowed.get(cur, []):
                return _err("INVALID_TRANSITION", f"Invalid track status transition {cur} -> fetching.")
            track_row["status"] = "fetching"
            track_row["updated_at"] = _now()
        # fetching -> unavailable
        if "unavailable" not in allowed.get(track_row.get("status"), []):
            return _err("INVALID_TRANSITION", f"Invalid track status transition {track_row.get('status')} -> unavailable.")
        track_row["status"] = "unavailable"
        track_row["failure_reason"] = reason
        track_row["updated_at"] = _now()
        # persist
        for i, t in enumerate(tracks):
            if t.get("id") == track_row.get("id"):
                tracks[i] = track_row
                break
        _save("transcript_tracks.json", tracks)
        return None

    uerr = _upsert_track_unavailable("Upstream fetch not available in offline datastore; transcript unavailable.")
    if uerr:
        _transition_request("failed", error_code="UPSTREAM_ERROR", error_message=uerr["error"]["message"], processing_ms=int((time.time() - _t0) * 1000))
        try: _log_call("error", request_id=request_id, request_key=request_key, video_id=video_row.get("id"), track_id=(track_row or {}).get("id"), error_code=uerr["error"]["code"], error_message=uerr["error"]["message"])
        except Exception: pass
        return uerr

    req_row["track_id"] = track_row.get("id")
    for i, r in enumerate(reqs):
        if r.get("id") == req_row["id"]:
            reqs[i] = req_row
            break
    _save("transcript_requests.json", reqs)

    _transition_request(
        "failed",
        error_code="TRANSCRIPT_UNAVAILABLE",
        error_message=track_row.get("failure_reason") or "Transcript unavailable for requested language.",
        processing_ms=int((time.time() - _t0) * 1000)
    )
    try: _log_call("error", request_id=request_id, request_key=request_key, video_id=video_row.get("id"), track_id=track_row.get("id"), error_code="TRANSCRIPT_UNAVAILABLE", error_message=track_row.get("failure_reason"))
    except Exception: pass
    return _err("NOT_FOUND", "Transcript unavailable for requested language.", error_code="TRANSCRIPT_UNAVAILABLE")

def list_videos(status=None, youtube_video_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0009000" if __import__("os").path.isdir("./environment_mix/0009000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
        return f"{prefix}_{ts}_{secrets.token_hex(8)}"

    def _log_call(status_code, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("log"),
            "endpoint": "list_videos",
            "status": status_code,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now()
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            return None
        rate = cfg.get("rate_limit_per_minute")
        daily = cfg.get("daily_quota")
        now = datetime.datetime.utcnow()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if isinstance(rate, int) and rate >= 0:
            cutoff = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                ts = r.get("created_at")
                if isinstance(ts, str):
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= cutoff:
                        cnt += 1
            if cnt >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(daily, int) and daily >= 0:
            cutoff = now - datetime.timedelta(days=1)
            cnt = 0
            for r in logs:
                ts = r.get("created_at")
                if isinstance(ts, str):
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= cutoff:
                        cnt += 1
            if cnt >= daily:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    limerr = _enforce_limits()
    if limerr:
        try: _log_call("error", error_code=limerr["error"]["code"], error_message=limerr["error"]["message"])
        except Exception: pass
        return limerr

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        err = _err("VALIDATION_ERROR", "limit must be an integer.")
        try: _log_call("error", error_code=err["error"]["code"], error_message=err["error"]["message"])
        except Exception: pass
        return err
    if not (1 <= limit <= 200):
        err = _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
        try: _log_call("error", error_code=err["error"]["code"], error_message=err["error"]["message"])
        except Exception: pass
        return err

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "unavailable", "deleted"):
            err = _err("VALIDATION_ERROR", "status must be one of: active, unavailable, deleted.")
            try: _log_call("error", error_code=err["error"]["code"], error_message=err["error"]["message"])
            except Exception: pass
            return err

    if youtube_video_id is not None and not isinstance(youtube_video_id, str):
        err = _err("VALIDATION_ERROR", "youtube_video_id must be a string.")
        try: _log_call("error", error_code=err["error"]["code"], error_message=err["error"]["message"])
        except Exception: pass
        return err

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            err = _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
            try: _log_call("error", error_code=err["error"]["code"], error_message=err["error"]["message"])
            except Exception: pass
            return err
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            raw_s = raw.decode("utf-8")
            if not raw_s.startswith("offset:"):
                raise ValueError("bad cursor")
            offset = int(raw_s.split(":", 1)[1])
            if offset < 0:
                raise ValueError("bad cursor offset")
        except Exception:
            err = _err("VALIDATION_ERROR", "Invalid cursor.")
            try: _log_call("error", error_code=err["error"]["code"], error_message=err["error"]["message"])
            except Exception: pass
            return err

    videos = _load("videos.json")
    if not isinstance(videos, list):
        videos = []

    rows = videos
