            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1 or "start" not in obj:
                _log("error", "VALIDATION_ERROR", "Invalid cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor")
            start = obj["start"]
            if not isinstance(start, int) or start < 0:
                _log("error", "VALIDATION_ERROR", "Invalid cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor")
            # Ensure cursor matches the same filter set (prevents mixing)
            for k in ("video_id", "lang", "status", "is_auto_generated"):
                if obj.get(k, None) != (locals()[k] if k in locals() else None):
                    _log("error", "VALIDATION_ERROR", "Cursor does not match current filters")
                    return _err("VALIDATION_ERROR", "Cursor does not match current filters")
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            _log("error", "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    tracks = _load("transcript_tracks.json")
