            return False
        if is_auto_generated is not None:
            if r.get("is_auto_generated", None) != is_auto_generated:
                return False
        return True

    filtered = [r for r in tracks if _match(r)]

    # Sort deterministically: updated_at desc, then id asc
    def _ts(v):
        if isinstance(v, str):
            return v
        return ""
    filtered.sort(key=lambda r: (_ts(r.get("updated_at")), str(r.get("id"))), reverse=True)

    total = len(filtered)
    page = filtered[start:start + limit]
    next_start = start + len(page)
    has_more = next_start < total

    next_cursor = None
    if has_more:
        payload = {
            "v": 1,
            "start": next_start,
            "video_id": video_id,
            "lang": lang,
            "status": status,
            "is_auto_generated": is_auto_generated
        }
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "object": "list",
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
    _log("ok")
    return resp

def update_transcript_track(id, status=None, failure_reason=None, source=None, is_auto_generated=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0009000" if __import__("os").path.isdir("./environment_mix/0009000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # ---- observable dynamics: request logging + rate limiting (only if request_logs.json exists) ----
    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _append_log(status_str, error=None):
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            return
        logs = _load_logs()
        rid = f"rlog_{int(time.time()*1000)}_{uuid.uuid4().hex[:8]}"
        row = {
            "id": rid,
            "endpoint": "update_transcript_track",
            "timestamp": now,
            "status": status_str,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error:
            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _check_rate_limit():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            return None
        logs = _load_logs()
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-5000:]):
            if r.get("endpoint") != "update_transcript_track":
                continue
            dt = _parse_ts(r.get("timestamp"))
            if dt is None:
                continue
            if dt < cutoff:
                break
            cnt += 1
            if cnt >= 120:
                return _err("RATE_LIMIT", "Too many requests to update_transcript_track; please retry later.", limit_per_minute=120)
        return None

    rl = _check_rate_limit()
    if rl:
        _append_log("error", rl["error"])
        return rl

    # ---- input validation ----
    if not isinstance(id, str) or not id.strip():
        e = _err("VALIDATION_ERROR", "id is required and must be a non-empty string.", field="id")
        _append_log("error", e["error"])
        return e

    allowed_status = {"available", "fetching", "failed", "unavailable"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            e = _err("VALIDATION_ERROR", "status must be one of: available, fetching, failed, unavailable.", field="status", allowed=sorted(allowed_status))
            _append_log("error", e["error"])
            return e

    if failure_reason is not None and not isinstance(failure_reason, str):
        e = _err("VALIDATION_ERROR", "failure_reason must be a string when provided.", field="failure_reason")
        _append_log("error", e["error"])
        return e

    if source is not None:
        if not isinstance(source, str) or source not in {"youtube_transcript_api", "other"}:
            e = _err("VALIDATION_ERROR", "source must be one of: youtube_transcript_api, other.", field="source", allowed=["youtube_transcript_api", "other"])
            _append_log("error", e["error"])
            return e

    if is_auto_generated is not None and not isinstance(is_auto_generated, bool):
        e = _err("VALIDATION_ERROR", "is_auto_generated must be a boolean when provided.", field="is_auto_generated")
        _append_log("error", e["error"])
        return e

    # ---- load store rows ----
    tracks = _load("transcript_tracks.json")
    if isinstance(tracks, dict) and "rows" in tracks and isinstance(tracks["rows"], list):
        tracks_rows = tracks["rows"]
        tracks_wrap = tracks
    elif isinstance(tracks, list):
        tracks_rows = tracks
        tracks_wrap = None
    else:
        tracks_rows = []
        tracks_wrap = None

    track = None
    idx = None
    for i, r in enumerate(tracks_rows):
        if isinstance(r, dict) and r.get("id") == id:
            track, idx = r, i
            break

    # The audit shows callers may (incorrectly) pass a video id into this tool.
    # To behave robustly and avoid spurious rejections, attempt to resolve:
    # if `id` is a videos.id, pick the "best" track for that video (prefer matching source if provided, else any).
    if track is None:
        vids = _load("videos.json")
        if isinstance(vids, dict) and "rows" in vids and isinstance(vids["rows"], list):
            vids_rows = vids["rows"]
        elif isinstance(vids, list):
            vids_rows = vids
        else:
            vids_rows = []

        is_video_id = any(isinstance(v, dict) and v.get("id") == id for v in vids_rows)
        if is_video_id:
            candidates = [r for r in tracks_rows if isinstance(r, dict) and r.get("video_id") == id]
            if source is not None:
                for i, r in enumerate(tracks_rows):
                    if isinstance(r, dict) and r.get("video_id") == id and r.get("source") == source:
                        track, idx = r, i
                        break
            if track is None and candidates:
                # Prefer non-deleted video track states: available > fetching > failed > unavailable
                pr = {"available": 3, "fetching": 2, "failed": 1, "unavailable": 0}
                best = max(candidates, key=lambda r: pr.get(r.get("status"), -1))
                track = best
                idx = tracks_rows.index(best)

    if track is None or idx is None:
        e = _err("NOT_FOUND", "Transcript track not found.", id=id)
        _append_log("error", e["error"])
        return e

    # ---- lifecycle transition validation ----
    transitions = {
        "fetching": {"available", "failed", "unavailable"},
        "available": {"fetching", "unavailable"},
        "failed": {"fetching", "unavailable"},
        "unavailable": {"fetching"},
    }
    cur_status = track.get("status")

    if status is not None and status != cur_status:
        if cur_status not in transitions:
            e = _err("VALIDATION_ERROR", "Current track status is invalid in datastore.", rule="transcript_tracks.status enum", current_status=cur_status, track_id=track.get("id"))
            _append_log("error", e["error"])
            return e
        if status not in transitions[cur_status]:
            e = _err(
                "INVALID_TRANSITION",
                f"Invalid status transition from '{cur_status}' to '{status}'.",
                rule="transcript_tracks.status transitions",
                from_status=cur_status,
                to_status=status,
                track_id=track.get("id"),
            )
            _append_log("error", e["error"])
            return e

    # ---- enforce content invariants when setting available ----
    # Business rule: refuse setting available without corresponding transcript content managed by the server.
    # Also enforce: when available, segment_count must equal number of segments for track.
    if status == "available":
        segs = _load("transcript_segments.json")
        if isinstance(segs, dict) and "rows" in segs and isinstance(segs["rows"], list):
            seg_rows = segs["rows"]
        elif isinstance(segs, list):
            seg_rows = segs
        else:
            seg_rows = []
        seg_count = sum(1 for s in seg_rows if isinstance(s, dict) and s.get("track_id") == track.get("id"))
        if seg_count <= 0:
            e = _err(
                "CONFLICT",
                "Cannot set status to 'available' because no transcript segments exist for this track.",
                rule="Refuse available without transcript content",
                track_id=track.get("id"),
            )
            _append_log("error", e["error"])
            return e

    # ---- apply updates ----
    new_status = cur_status if status is None else status

    # failure_reason rule (fix): allow passing failure_reason with ANY status input, but only persist it
    # when resulting status is failed/unavailable; otherwise clear it (do not reject the request).
    new_failure_reason = track.get("failure_reason")
    if failure_reason is not None:
        if new_status in {"failed", "unavailable"}:
            new_failure_reason = failure_reason
        else:
            new_failure_reason = None
    else:
        if new_status in {"available", "fetching"}:
            new_failure_reason = None

    # source: set if provided; else keep as-is
    new_source = track.get("source")
    if source is not None:
        new_source = source

    # is_auto_generated: update if provided
    new_is_auto = track.get("is_auto_generated")
    if is_auto_generated is not None:
        new_is_auto = is_auto_generated

    # segment_count + last_fetched_at adjustments
    seg_rows = None
    seg_count_for_track = None
    if new_status == "available":
        segs = _load("transcript_segments.json")
        if isinstance(segs, dict) and "rows" in segs and isinstance(segs["rows"], list):
            seg_rows = segs["rows"]
        elif isinstance(segs, list):
            seg_rows = segs
        else:
            seg_rows = []
        seg_count_for_track = sum(1 for s in seg_rows if isinstance(s, dict) and s.get("track_id") == track.get("id"))
    elif new_status in {"failed", "unavailable"}:
        # segment_count should not increase; leave as-is
        seg_count_for_track = None
    elif new_status == "fetching":
        seg_count_for_track = None

    updated = dict(track)
    updated["status"] = new_status
    updated["failure_reason"] = new_failure_reason
    updated["source"] = new_source
    updated["is_auto_generated"] = new_is_auto
    updated["updated_at"] = now

    if new_status == "available":
        updated["last_fetched_at"] = now
        # Enforce invariant: segment_count equals segment rows count
        updated["segment_count"] = int(seg_count_for_track or 0)
        # Optional: update text_plain if absent; do not fabricate if no segments list accessible
        if seg_rows is not None:
            texts = []
            for s in seg_rows:
                if isinstance(s, dict) and s.get("track_id") == track.get("id"):
                    t = s.get("text")
                    if isinstance(t, str):
                        texts.append(t)
            if texts:
                updated["text_plain"] = " ".join(t.strip() for t in texts if t is not None and str(t).strip() != "").strip() or updated.get("text_plain")
    elif new_status in {"fetching"}:
        # do not claim last_fetched_at on fetching
        pass

    # Must have an actual effect (NO SUCCESS WITHOUT EFFECT)
    if updated == track:
        e = _err("CONFLICT", "No changes to apply to transcript track.", rule="No-op update refused", track_id=track.get("id"))
        _append_log("error", e["error"])
        return e

    tracks_rows[idx] = updated
    if tracks_wrap is not None:
        tracks_wrap["rows"] = tracks_rows
        _save("transcript_tracks.json", tracks_wrap)
    else:
        _save("transcript_tracks.json", tracks_rows)

    resp = {"track": updated}
    _append_log("ok", None)
    return resp
